class RemoteLockoutTargetTest {
    @Test
    fun validatesBoundedResultReceiptLifetimeAndTrustedClock() {
        val proof = RemoteCommandResultReceiptProof(
            acceptedAt = "2026-09-05T12:00:00Z",
            commandId = "018f4f45-4d34-7d98-a6c5-4de1bd63a21c",
            coordinatorAudience = CoordinatorAudience.CurfewDeviceAgent,
            deviceId = "018f4f45-7a98-7f53-89af-a4805f705d20",
            expiresAt = "2026-09-05T12:05:00Z",
            resultDigest = "D".repeat(43),
            sequence = 42,
        )

        assertEquals(proof, proof.validated(java.time.Instant.parse("2026-09-05T12:04:59Z")))
        assertFailsWith<CurfewProtocolValidationException> {
            proof.copy(expiresAt = "2026-09-05T12:00:00Z").validated()
        }
        assertFailsWith<CurfewProtocolValidationException> {
            proof.copy(expiresAt = "2026-09-05T12:05:01Z").validated()
        }
        assertFailsWith<CurfewProtocolValidationException> {
            proof.copy(
                acceptedAt = "2026-09-05T12:00:00.000Z",
                expiresAt = "2026-09-05T12:05:00.001Z",
            ).validated()
        }
        assertFailsWith<CurfewProtocolValidationException> {
            proof.validated(java.time.Instant.parse("2026-09-05T12:05:01Z"))
        }
    }

    private val json = Json { ignoreUnknownKeys = false }

    @Test
    fun rejectsAbsentMixedAndFalseSelectors() {
        for (payload in listOf(
            "{}",
            """{"deviceIds":["018f4f45-7a98-7f53-89af-a4805f705d20"],"allOptedInDevices":true}""",
            """{"allOptedInDevices":false}""",
        )) {
            val target = json.decodeFromString<RemoteLockoutTarget>(payload)
            assertFailsWith<CurfewProtocolValidationException> { target.validated() }
        }
    }

    @Test
    fun acceptsExactlyOneSelector() {
        assertNotNull(
            json.decodeFromString<RemoteLockoutTarget>(
                """{"deviceIds":["018f4f45-7a98-7f53-89af-a4805f705d20"]}""",
            ).validated(),
        )
        assertNotNull(
            json.decodeFromString<RemoteLockoutTarget>(
                """{"allOptedInDevices":true}""",
            ).validated(),
        )
    }

    @Test
    fun rejectsNoncanonicalAndOversizedSelections() {
        assertFailsWith<CurfewProtocolValidationException> {
            json.decodeFromString<RemoteLockoutTarget>(
                """{"deviceIds":["018F4F45-7A98-7F53-89AF-A4805F705D20"]}""",
            ).validated()
        }
        val oversized = (0 until 33).map { index ->
            "018f4f45-7a98-7f53-89af-${index.toString(16).padStart(12, '0')}"
        }
        assertFailsWith<CurfewProtocolValidationException> {
            RemoteLockoutTarget(deviceIds = oversized).validated()
        }
    }

    @Test
    fun rejectsDuplicateCoordinatorKeyIdentifiers() {
        val payload = """{"keys":[{"alg":"ES256","crv":"P-256","kid":"same","kty":"EC","use":"sig","x":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","y":"BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB"},{"alg":"ES256","crv":"P-256","kid":"same","kty":"EC","use":"sig","x":"CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC","y":"DDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDD"}]}"""
        assertFailsWith<CurfewProtocolValidationException> {
            json.decodeFromString<RemoteCommandJWKS>(payload).validated()
        }
    }
